@classmethod
def _coschedules(cls, cmd: str) -> bool:
    """True if a single command already runs a background proc together
    with something else (has a bare & AND more work after it, or uses
    wait/&&) — i.e. the agent is doing it correctly in-call."""
    has_bg = bool(_BG_SEGMENT.search(cmd))
    if not has_bg:
        return False
    if re.search(r"&(?!&)\s*\S", cmd) or "wait" in cmd.lower():
        return True
    return False

